### ① Concept Explanation

Tool output parsing transforms raw tool results (strings, JSON, bytes) into structured data the LLM can reason about. Error handling covers the full spectrum: validation errors (wrong arg types), runtime errors (API timeout), logical errors (empty results), and cascading failures (tool A's failure breaks tool B that depends on it). A production tool layer must: validate outputs against expected schemas, handle partial results gracefully, propagate errors in a structured format the LLM can understand and self-correct from, and log all failures with full context for debugging.

### ② Core Implementation

```python
import json
import logging
from typing import Any
from pydantic import BaseModel, ValidationError
from tenacity import retry, stop_after_attempt, wait_exponential, retry_if_exception_type

logger = logging.getLogger(__name__)

class ToolResult(BaseModel):
    """Standardized tool output format."""
    success: bool
    data: Any = None
    error_type: str | None = None
    error_message: str | None = None
    tool_name: str = ""
    execution_time_ms: float = 0.0

    def to_llm_string(self) -> str:
        """Format result for LLM consumption."""
        if self.success:
            return f"SUCCESS: {json.dumps(self.data)}"
        return (
            f"ERROR [{self.error_type}]: {self.error_message}. "
            f"Please adjust your approach or use a different tool."
        )

class ToolExecutor:
    """Production tool executor with parsing, validation, and error handling."""

    def __init__(self, output_schemas: dict[str, type[BaseModel]] = None):
        self.output_schemas = output_schemas or {}

    @retry(
        stop=stop_after_attempt(3),
        wait=wait_exponential(min=1, max=8),
        retry=retry_if_exception_type((ConnectionError, TimeoutError)),
        before_sleep=lambda rs: logger.warning(f"Retry {rs.attempt_number}/3..."),
    )
    def execute(self, tool_name: str, executor_fn: callable, **kwargs) -> ToolResult:
        import time
        start = time.monotonic()
        try:
            raw_result = executor_fn(**kwargs)
            elapsed = (time.monotonic() - start) * 1000

            # Parse and validate output
            parsed = self._parse_output(tool_name, raw_result)

            return ToolResult(
                success=True,
                data=parsed,
                tool_name=tool_name,
                execution_time_ms=elapsed,
            )

        except ValidationError as e:
            logger.error(f"Tool '{tool_name}' output validation failed: {e}")
            return ToolResult(success=False, error_type="VALIDATION_ERROR",
                              error_message=str(e), tool_name=tool_name)
        except TimeoutError as e:
            logger.error(f"Tool '{tool_name}' timed out")
            raise  # Let tenacity retry
        except Exception as e:
            logger.error(f"Tool '{tool_name}' failed: {e}", exc_info=True)
            return ToolResult(success=False, error_type="RUNTIME_ERROR",
                              error_message=str(e), tool_name=tool_name)

    def _parse_output(self, tool_name: str, raw: Any) -> Any:
        """Parse and optionally validate tool output."""
        # Try JSON parsing if string
        if isinstance(raw, str):
            try:
                parsed = json.loads(raw)
            except json.JSONDecodeError:
                parsed = raw  # Keep as string
        else:
            parsed = raw

        # Validate against Pydantic schema if registered
        if tool_name in self.output_schemas:
            schema_class = self.output_schemas[tool_name]
            if isinstance(parsed, dict):
                validated = schema_class(**parsed)
                return validated.model_dump()

        return parsed
```

