from dataclasses import dataclass, field
from typing import Optional
import networkx as nx

@dataclass
class ToolCall:
    id: str
    tool_name: str
    args: dict
    depends_on: list[str] = field(default_factory=list)  # IDs of required prior calls
    result: Optional[str] = None

class ToolChainExecutor:
    """Execute tool chains respecting dependencies using topological sort."""

    def execute_chain(self, calls: list[ToolCall], executors: dict) -> dict[str, str]:
        # Build dependency graph
        G = nx.DiGraph()
        call_map = {c.id: c for c in calls}
        for call in calls:
            G.add_node(call.id)
            for dep in call.depends_on:
                G.add_edge(dep, call.id)

        # Detect cycles
        if not nx.is_directed_acyclic_graph(G):
            raise ValueError("Circular dependency in tool chain!")

        results = {}
        for call_id in nx.topological_sort(G):
            call = call_map[call_id]

            # Inject dependency results into args
            args = call.args.copy()
            for dep_id in call.depends_on:
                args[f"from_{dep_id}"] = results[dep_id]

            try:
                result = executors[call.tool_name](**args)
                results[call_id] = str(result)
            except Exception as e:
                results[call_id] = f"ERROR: {e}"

        return results
