import logging
from dataclasses import dataclass

logger = logging.getLogger(__name__)

@dataclass
class ToolSelectionAudit:
    query: str
    expected_tool: str
    actual_tool: str
    tool_description_used: str
    is_correct: bool

class WrongToolDebugger:
    """Systematic debugging when agent picks wrong tool repeatedly."""

    def __init__(self, tools: list[dict]):
        self.tools = {t["function"]["name"]: t for t in tools}
        self.audit_log: list[ToolSelectionAudit] = []

    def record(self, query: str, selected_tool: str, expected_tool: str = None) -> None:
        self.audit_log.append(ToolSelectionAudit(
            query=query,
            expected_tool=expected_tool or "unknown",
            actual_tool=selected_tool,
            tool_description_used=self.tools.get(selected_tool, {}).get("function", {}).get("description", ""),
            is_correct=(selected_tool == expected_tool),
        ))

    def analyze_failures(self) -> str:
        """Identify patterns in wrong tool selections."""
        wrong = [a for a in self.audit_log if not a.is_correct]
        if not wrong:
            return "No wrong tool selections recorded."

        report_lines = [
            f"Wrong tool selections: {len(wrong)}/{len(self.audit_log)} "
            f"({len(wrong)/len(self.audit_log)*100:.1f}%)"
        ]
        for audit in wrong:
            report_lines.append(
                f"  Query: '{audit.query[:80]}...'\n"
                f"  Expected: {audit.expected_tool}\n"
                f"  Got: {audit.actual_tool}\n"
                f"  Tool description: '{audit.tool_description_used[:100]}...'"
            )
        return "\n".join(report_lines)

    def suggest_fixes(self) -> list[str]:
        """Suggest schema improvements based on wrong selections."""
        suggestions = []
        wrong_tools = {a.actual_tool for a in self.audit_log if not a.is_correct}
        for tool_name in wrong_tools:
            suggestions.append(
                f"Tool '{tool_name}': Add 'Do NOT use for: [confused cases]' to description."
            )
        return suggestions
